from __future__ import annotations
import logging
import re
import tarfile
from pathlib import Path

from taf.transport.ssh.connection import SSHConnection

from .util import sh_quote


def escape_path(path):
    """Escape any path (directory or file paths) for any occurrence of special characters.
    """
    if isinstance(path, list):
        return " ".join(escape_path(p) for p in path)
    elif isinstance(path, str) and '/' in path:
        return f'{re.escape(str(Path(path).parent))}/{Path(path).name}'
    return path


class FileCollector:
    """Class downloads files and stores them in organized way.

    Traffic transmission is compressed to make it more efficient. Before transmission class will copy specified files into
    temporary directory to avoid case where tar application is not able to compress files.
    """

    def __init__(self, temp_dir: Path = Path("/tmp")):
        self.ssh = None
        self._logger = self._create_logger()
        self.file_organizer_dir = temp_dir / "file_organizer"

    def connect(self, ssh_connection: SSHConnection):
        """Use given ssh_connection object for communication

        :param ssh_connection: existing SSH connection object
        :type ssh_connection: SSHConnection
        """
        self.ssh = ssh_connection

    def get_files(self, files_pattern: str, destination: Path, unzip: bool, destination_is_dir: bool = True) -> None:
        """Get files that match the FILE_PATTERN compressed as tar.gz via SSH from host.

        :param str          files_pattern:   Glob pattern of files to get.
        :param Path         destination:    Destination path where tar file should be stored.
        :param bool         unzip:          Flag determines that downloaded tar must be unzipped.
        :param bool         destination_is_dir:
        """
        remote_tar_path = self._create_remote_tar_gz_file(files_pattern)

        self._remove_remote_files(files_pattern)

        destination.parent.mkdir(exist_ok=True, parents=True)
        local_tar_path = (
            (destination.parent if destination.parent != Path("/") else destination) / "temporary_file.tar.gz"
            if not str(destination).endswith(".tar.gz")
            else destination
        )
        self._logger.debug(f"Downloading tar file {remote_tar_path} to {local_tar_path}")
        self.ssh.files.get(remote_tar_path, local_path=local_tar_path)

        if unzip:
            self._unpack_files(
                tar_gz_path=local_tar_path,
                path=(destination if destination_is_dir else destination.parent)
            )
            self._remove_file(local_tar_path)

        self._remove_remote_directory(self.file_organizer_dir)
        self._remove_remote_files(remote_tar_path)

    def _create_remote_tar_gz_file(self, files_pattern: str) -> str:
        self._create_remote_directory(self.file_organizer_dir)
        self._copy_files_to_remote_tmp_directory(files_pattern)
        return self._pack_remote_tmp_directory()

    def _create_remote_directory(self, path: Path) -> None:
        cmd = f"mkdir -p {sh_quote(path)}"
        self._execute_cmd_and_log_info(cmd)

    def _copy_files_to_remote_tmp_directory(self, files_pattern: str) -> None:
        cmd = f"cp {sh_quote(files_pattern)} {self.file_organizer_dir}"
        self._execute_cmd_and_log_info(cmd)

    def _pack_remote_tmp_directory(self) -> str:
        tar_gz_file_path = f"{self.file_organizer_dir}.tar.gz"
        cmd = f"tar -zcvf {tar_gz_file_path} -C {self.file_organizer_dir} $(ls {self.file_organizer_dir})"
        self._execute_cmd_and_log_info(cmd)
        return tar_gz_file_path

    def _remove_remote_directory(self, path) -> None:
        cmd = f"rm -rf {sh_quote(path)}"
        self._execute_cmd_and_log_info(cmd)

    def _unpack_files(self, tar_gz_path, path) -> None:
        self._logger.debug(f"Extracting {tar_gz_path}")
        tar_file = tarfile.open(tar_gz_path)
        tar_file.extractall(path=path)
        tar_file.close()

    def _remove_file(self, tar_gz_path) -> None:
        self._logger.debug(f"Removing file {tar_gz_path}")
        Path(tar_gz_path).unlink()

    def _remove_remote_files(self, files: str) -> None:
        files = sh_quote(files)
        self._logger.debug(f"Removing file(s) matching pattern: {files}")
        cmd = f"rm -f {files}"
        self._execute_cmd_and_log_info(cmd)

    def _execute_cmd_and_log_info(self, cmd: str) -> None:
        self._logger.debug(f"Executing command on remote host: {cmd}")
        output = self.ssh.execute(cmd)
        if output != "":
            self._logger.debug(f"Command output:\n{output}")

    @staticmethod
    def _create_logger() -> logging.Logger:
        logger = logging.getLogger(__name__)
        return logger
